import React, { useState } from 'react';
import API from '../api/axiosClient';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { FaWallet, FaCreditCard, FaHistory, FaArrowUp, FaArrowDown, FaPlusCircle, FaExclamationTriangle, FaCalendarAlt } from 'react-icons/fa';

export default function CustomerDashboard({ orgId }) {
    const queryClient = useQueryClient();
    const [topupAmount, setTopupAmount] = useState('');
    const [feedback, setFeedback] = useState('');
    const [selectedMonth, setSelectedMonth] = useState(new Date().getMonth() + 1);
    const [selectedYear, setSelectedYear] = useState(new Date().getFullYear());

    // Fetch Customer Profile (Balance & RFID UID)
    const { data: profile, isLoading: profileLoading } = useQuery({
        queryKey: ['customerProfile', orgId],
        queryFn: async () => {
            const res = await API.get(`/auth/${orgId}/me`);
            return res.data;
        }
    });

    // Fetch Customer Transaction History filtered by Month and Year
    const { data: transactions, isLoading: txLoading } = useQuery({
        queryKey: ['customerTransactions', orgId, selectedMonth, selectedYear],
        queryFn: async () => {
            const res = await API.get(`/auth/${orgId}/transactions?month=${selectedMonth}&year=${selectedYear}`);
            return res.data;
        }
    });

    // Fetch Active Pending Tap Status for this customer
    const { data: pendingStatus } = useQuery({
        queryKey: ['customerPending', orgId, profile?._id],
        queryFn: async () => {
            if (!profile?._id) return { hasPending: false };
            const res = await API.get(`/worker/${orgId}/customer/${profile._id}/pending`);
            return res.data;
        },
        enabled: !!profile?._id,
        refetchInterval: 2000
    });

    // Top-up Mutation
    const topupMutation = useMutation({
        mutationFn: async (amount) => await API.post(`/payment/${orgId}/topup`, { amount }),
        onSuccess: (res) => {
            setFeedback(`Successfully added $${topupAmount} to your wallet!`);
            setTopupAmount('');
            queryClient.invalidateQueries(['customerProfile', orgId]);
            queryClient.invalidateQueries(['customerTransactions', orgId]);
        },
        onError: (err) => setFeedback(err.response?.data?.error || 'Top-up failed')
    });

    if (profileLoading) return <div className="text-gray-400 text-center mt-12">Loading dashboard...</div>;

    return (
        <div className="space-y-8">
            <h1 className="text-3xl font-bold flex items-center gap-2">
                <FaWallet className="text-indigo-400" /> Customer Portal
            </h1>

            {feedback && (
                <div className="p-4 bg-indigo-950 border border-indigo-700/50 rounded-xl text-indigo-200 shadow-lg">
                    {feedback}
                </div>
            )}

            {/* Transparent Waiting Notification Banner */}
            {pendingStatus?.hasPending && (
                <div className="bg-amber-500/10 border-2 border-amber-500 text-amber-300 p-5 rounded-xl shadow-lg flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 animate-pulse">
                    <div className="flex items-center gap-3">
                        <FaExclamationTriangle className="text-amber-400 text-2xl flex-shrink-0" />
                        <div>
                            <h4 className="font-bold text-base text-amber-200">Charge Waiting for Physical Tap</h4>
                            <p className="text-sm text-amber-300/90 mt-0.5">
                                A charge of <span className="font-bold text-white">${pendingStatus.amount}</span> has been initialized. 
                                Please tap your RFID card on terminal <span className="font-mono font-bold text-white">{pendingStatus.machineId}</span>.
                            </p>
                        </div>
                    </div>
                    <span className="bg-amber-500 text-gray-950 text-xs px-3 py-1.5 rounded-full font-bold uppercase tracking-wider self-end sm:self-auto">
                        {pendingStatus.status}
                    </span>
                </div>
            )}

            {/* Overview Cards */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* Wallet Balance Card */}
                <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 shadow-xl flex flex-col justify-between">
                    <div>
                        <span className="text-sm text-gray-400 flex items-center gap-1.5">
                            <FaWallet className="text-indigo-400" /> Current Balance
                        </span>
                        <h2 className="text-4xl font-extrabold text-white mt-2 font-mono">
                            ${profile?.balance?.toFixed(2) || '0.00'}
                        </h2>
                    </div>
                    <div className="mt-4 pt-4 border-t border-gray-700 text-sm text-gray-400">
                        Account: <strong className="text-white">{profile?.email}</strong>
                    </div>
                </div>

                {/* RFID Card Status Card */}
                <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 shadow-xl flex flex-col justify-between">
                    <div>
                        <span className="text-sm text-gray-400 flex items-center gap-1.5">
                            <FaCreditCard className="text-emerald-400" /> Linked RFID Card
                        </span>
                        <div className="mt-2 text-xl font-mono font-bold text-emerald-300">
                            {profile?.rfidUid ? profile.rfidUid : <span className="text-yellow-400 text-sm font-normal">Not linked yet (Ask store worker)</span>}
                        </div>
                    </div>
                    <div className="mt-4 pt-4 border-t border-gray-700 text-xs text-gray-400">
                        Tap this physical card at store terminals for instant automated deductions.
                    </div>
                </div>
            </div>

            {/* Top-Up Section */}
            <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 shadow-xl">
                <h3 className="text-xl font-semibold mb-4 flex items-center gap-2 text-indigo-400">
                    <FaPlusCircle /> Add Funds via Stripe
                </h3>
                <div className="flex gap-4 max-w-lg">
                    <input 
                        type="number" 
                        placeholder="Enter amount ($)" 
                        value={topupAmount}
                        onChange={(e) => setTopupAmount(e.target.value)}
                        className="flex-1 p-3 bg-gray-900 border border-gray-700 rounded-lg text-white focus:outline-none focus:border-indigo-500 font-mono"
                    />
                    <button 
                        onClick={() => topupMutation.mutate(parseFloat(topupAmount))}
                        className="bg-indigo-600 hover:bg-indigo-500 px-6 py-3 rounded-lg font-semibold transition whitespace-nowrap"
                    >
                        Top Up
                    </button>
                </div>
            </div>

            {/* Personal Transaction History Table with Month/Year Sort Controls */}
            <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 shadow-xl space-y-6">
                <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                    <h3 className="text-xl font-semibold flex items-center gap-2 text-indigo-400">
                        <FaHistory /> My Transaction History
                    </h3>

                    {/* Month and Year Filter Controls */}
                    <div className="flex items-center gap-3">
                        <FaCalendarAlt className="text-gray-400" />
                        <select 
                            value={selectedMonth} 
                            onChange={(e) => setSelectedMonth(e.target.value)}
                            className="p-2.5 bg-gray-900 border border-gray-700 rounded-lg text-white text-sm"
                        >
                            {Array.from({ length: 12 }, (_, i) => (
                                <option key={i + 1} value={i + 1}>
                                    {new Date(0, i).toLocaleString('default', { month: 'long' })}
                                </option>
                            ))}
                        </select>

                        <select 
                            value={selectedYear} 
                            onChange={(e) => setSelectedYear(e.target.value)}
                            className="p-2.5 bg-gray-900 border border-gray-700 rounded-lg text-white text-sm"
                        >
                            <option value="2025">2025</option>
                            <option value="2026">2026</option>
                        </select>
                    </div>
                </div>

                {txLoading ? (
                    <div className="text-gray-400">Loading history...</div>
                ) : transactions?.length === 0 ? (
                    <div className="text-gray-500 text-sm py-4">No transactions recorded for this period.</div>
                ) : (
                    <div className="overflow-x-auto">
                        <table className="w-full text-left text-sm text-gray-300">
                            <thead className="bg-gray-900 uppercase text-xs text-gray-400 border-b border-gray-700">
                                <tr>
                                    <th className="p-3">Type</th>
                                    <th className="p-3">Amount</th>
                                    <th className="p-3">Reference / Machine</th>
                                    <th className="p-3">Date</th>
                                </tr>
                            </thead>
                            <tbody>
                                {transactions?.map((tx) => (
                                    <tr key={tx._id} className="border-b border-gray-700/50 hover:bg-gray-750">
                                        <td className="p-3">
                                            {tx.type === 'TOPUP' ? (
                                                <span className="text-emerald-400 flex items-center gap-1 font-semibold"><FaArrowUp /> Top-Up</span>
                                            ) : (
                                                <span className="text-indigo-400 flex items-center gap-1 font-semibold"><FaArrowDown /> Purchase</span>
                                            )}
                                        </td>
                                        <td className="p-3 font-mono font-bold">${tx.finalPaid.toFixed(2)}</td>
                                        <td className="p-3 text-gray-400">{tx.machineId || 'Stripe Gateway'}</td>
                                        <td className="p-3 text-gray-400">{new Date(tx.createdAt).toLocaleString()}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>
        </div>
    );
}
